SELECT id, balance, opened_date, status, LAG(balance, 1) OVER (PARTITION BY customer_id ORDER BY opened_date, id) prev_balance, FIRST_VALUE(status) IGNORE NULLS OVER (PARTITION BY status ORDER BY opened_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) first_known_status, NTILE(3) OVER (PARTITION BY YEAR(opened_date), account_type ORDER BY balance, id) balance_bucket, ROW_NUMBER() OVER (ORDER BY opened_date DESC, id) event_seq FROM accounts
